const fs = require('fs');
const fetch = require('node-fetch');

const API_KEY = process.env.CROSSMINT_API_KEY;
const MINT_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const ACTION_URL_BASE = 'https://staging.crossmint.com/api/2022-06-09/actions/';

async function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

async function run() {
    let result = {
        actionId: "mock-action-id",
        final_status: "unknown",
        poll_attempts: 0,
        mint_chain: "polygon-amoy"
    };

    try {
        if (!API_KEY) {
            throw new Error("Missing CROSSMINT_API_KEY");
        }

        const mintRes = await fetch(MINT_URL, {
            method: 'POST',
            headers: {
                'X-API-KEY': API_KEY,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                recipient: "email:demo@example.com:polygon-amoy",
                metadata: {
                    name: "Poll Test NFT",
                    description: "Testing async polling",
                    image: "https://example.com/poll.png"
                }
            })
        });

        if (!mintRes.ok) {
            const text = await mintRes.text();
            throw new Error(`Mint failed: ${mintRes.status} ${text}`);
        }

        const mintData = await mintRes.json();
        result.actionId = mintData.actionId || mintData.id;

        let status = "pending";
        let attempts = 0;
        const maxAttempts = 5;

        while (status === "pending" && attempts < maxAttempts) {
            attempts++;
            result.poll_attempts = attempts;

            await sleep(2000);

            const actionRes = await fetch(`${ACTION_URL_BASE}${result.actionId}`, {
                method: 'GET',
                headers: {
                    'X-API-KEY': API_KEY
                }
            });

            if (!actionRes.ok) {
                const text = await actionRes.text();
                throw new Error(`Action poll failed: ${actionRes.status} ${text}`);
            }

            const actionData = await actionRes.json();
            status = actionData.status;
            result.final_status = status;
        }
    } catch (err) {
        result.error = err.message;
    }

    fs.writeFileSync('/home/user/poll_result.json', JSON.stringify(result, null, 2));
}

run();

